import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tanh_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor tanh_forward(torch::Tensor x);
"""

tanh_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Elementwise Tanh kernel using CuTe tensors/layouts.
// Each CTA processes a tile of Threads*Vec contiguous elements.
// Threads own Vec contiguous elements so CuTe copy vectorizes to 128-bit loads/stores.
template <typename T, int Threads, int Vec>
__global__ void tanh_kernel(const T* __restrict__ X,
                            T* __restrict__ Y,
                            int64_t N)
{
  constexpr int Tile = Threads * Vec;

  // Global tensors as flat 1-D CuTe tensors
  Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N), make_stride(Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N), make_stride(Int<1>{}));

  const int64_t tile_begin = (int64_t)blockIdx.x * Tile;

  if (tile_begin + Tile <= N) {
    // Fast path: full tile, vectorized via CuTe copy
    auto cta_tiler = make_shape(Int<Tile>{});
    auto cta_coord = make_coord((int)blockIdx.x);
    Tensor gX = local_tile(mX, cta_tiler, cta_coord);  // (Tile)
    Tensor gY = local_tile(mY, cta_tiler, cta_coord);  // (Tile)

    // Thread layout: each thread owns Vec contiguous elements
    auto tLayout = make_layout(make_shape(Int<Threads>{}, Int<Vec>{}),
                               make_stride(Int<Vec>{}, Int<1>{}));

    Tensor tXgX = local_partition(gX, tLayout, threadIdx.x);  // (Vec) gmem
    Tensor tYgY = local_partition(gY, tLayout, threadIdx.x);  // (Vec) gmem

    // Register fragment
    Tensor tXrX = make_tensor<T>(make_shape(Int<Vec>{}));

    // Vectorized global -> register copy (128-bit when alignment allows)
    copy(tXgX, tXrX);

    // Apply tanh on registers
    #pragma unroll
    for (int i = 0; i < Vec; ++i) {
      tXrX(i) = tanhf(tXrX(i));
    }

    // Vectorized register -> global copy
    copy(tXrX, tYgY);
  } else {
    // Boundary path: scalar with bounds checking
    int64_t idx = tile_begin + (int64_t)threadIdx.x * Vec;
    #pragma unroll
    for (int v = 0; v < Vec; ++v) {
      int64_t i = idx + v;
      if (i < N) {
        mY(i) = tanhf(mX(i));
      }
    }
  }
}

torch::Tensor tanh_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  const int64_t N = x_c.numel();
  if (N == 0) {
    return y;
  }

  constexpr int Threads = 256;
  constexpr int Vec = 4;
  constexpr int Tile = Threads * Vec;

  const int64_t num_blocks = (N + Tile - 1) / Tile;
  TORCH_CHECK(num_blocks <= (int64_t)0x7fffffff, "Tensor too large for launch");

  dim3 block(Threads);
  dim3 grid((unsigned)num_blocks);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  tanh_kernel<float, Threads, Vec><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      N
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "tanh_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=tanh_cpp_decl,
    cuda_sources=tanh_cuda_src,
    functions=["tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CuTe CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.tanh_forward(x)

